"""Literal original drawer in independent desktop-sized browsing contexts."""
from pathlib import Path
import json
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download'
lines=(r/'docs/replica/source/original.js').read_text().splitlines()
starts=('const esc=','const icons=','const icon=','const t=','const btn=','const notice=','function matchingOptions(','function openModal(','function closeModal(')
defs='\n'.join(s for s in lines if s.startswith(starts))
assert 'const btn=' in defs
(o/'matchingdialog-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes())
cases=[dict(id=f'{lang}-{w}-{h}-{query or "all"}',lang=lang,width=w,height=h,query=query)for lang in ['ko','en']for w in [960,1280]for h in [600,720,960]for query in ['', ' ARCHIVE ', 'NO_SUCH_TABLE','demo.orders']]
frame='''<!doctype html><meta charset="utf-8"><link rel="stylesheet" href="http://10.211.55.2:8768/matchingdialog-original.css"><style>dialog{animation:none!important}*{transition:none!important}</style><button id="opener">Open</button><div id="dialog-host"></div><script>let lang=CASE.lang,modal=null,state={maps:{'demo.customers':'demo.customers','demo.orders':'demo.orders','demo.line_items':'demo.line_items'}};'''+defs+''';document.getElementById('opener').focus();openModal('mapping','demo.customers');if(CASE.query){document.getElementById('match-search').value=CASE.query;document.getElementById('match-options').innerHTML=matchingOptions(CASE.query);document.getElementById('match-query-note').textContent=t('검색은 대응을 바꾸지 않습니다. 선택 후 적용하세요.','Searching does not change the match. Select a target, then apply.')}window.fixtureReady=document.fonts.ready;</script>'''
read='''function read(f){const doc=f.contentDocument,d=doc.querySelector('dialog'),r=d.getBoundingClientRect(),box=e=>{let b=e.getBoundingClientRect();return{x:b.x,y:b.y,width:b.width,height:b.height}},parts={dialog:d,head:d.querySelector('.dialog-head'),title:d.querySelector('h2'),close:d.querySelector('.dialog-head button'),body:d.querySelector('.dialog-body'),source:d.querySelector('.match-source'),sourceLabel:d.querySelector('.match-source small'),targetLabel:d.querySelector('h3'),search:d.querySelector('.search-field'),list:d.querySelector('.match-list'),note:d.querySelector('#match-query-note'),policy:d.querySelector('.small'),footer:d.querySelector('.dialog-footer'),cancel:d.querySelector('.dialog-footer button'),apply:d.querySelector('.dialog-footer button.primary')};return{id:f.dataset.id,environment:{innerWidth:f.contentWindow.innerWidth,innerHeight:f.contentWindow.innerHeight,clientWidth:doc.documentElement.clientWidth,clientHeight:doc.documentElement.clientHeight,minWidth:f.contentWindow.getComputedStyle(doc.documentElement).minWidth,minHeight:f.contentWindow.getComputedStyle(doc.documentElement).minHeight},parts:Object.fromEntries(Object.entries(parts).map(([k,e])=>[k,box(e)])),cards:[...d.querySelectorAll('.match-option')].map(e=>({name:e.querySelector('input').value,selected:e.querySelector('input').checked,disabled:e.querySelector('input').disabled,box:box(e)})),texts:{title:parts.title.textContent,sourceLabel:parts.sourceLabel.textContent,targetLabel:parts.targetLabel.textContent,note:parts.note.textContent,policy:parts.policy.textContent,cancel:parts.cancel.textContent,apply:parts.apply.textContent},bodyScrollHeight:parts.body.scrollHeight,listScrollHeight:parts.list.scrollHeight,bodyScrollTop:parts.body.scrollTop,listScrollTop:parts.list.scrollTop,draft:f.contentWindow.modal?.draft??'demo.customers',empty:doc.querySelector('.table-empty')?.textContent??null,shadow:f.contentWindow.getComputedStyle(d).boxShadow};}'''
script='const cases='+json.dumps(cases,ensure_ascii=False)+';const frame='+json.dumps(frame,ensure_ascii=False).replace('</','<\\/')+''';const ready=[];for(const c of cases){const f=document.createElement('iframe');f.dataset.id=c.id;f.style.width=c.width+'px';f.style.height=c.height+'px';f.srcdoc=frame.replaceAll('CASE',JSON.stringify(c));ready.push(new Promise(res=>f.onload=async()=>{await f.contentWindow.fixtureReady;res()}));document.getElementById('fixtures').append(f)}'''+read+'''document.getElementById('matchingdialog-record').onclick=async()=>{await Promise.all(ready);const rows=[...document.querySelectorAll('iframe')].map(read);const response=await fetch('/evidence/source-sidebar.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows})});if(!response.ok)throw Error('Evidence failed');document.getElementById('matchingdialog-record').textContent='MatchingDialog recorded';};'''
(o/'matchingdialog.html').write_text('<!doctype html><meta charset="utf-8"><title>MatchingDialog · original isolation</title><style>iframe{position:absolute;left:0;top:100px;border:0}iframe:not(:first-child){visibility:hidden}button{position:fixed;top:10px;left:10px;z-index:2}</style><button id="matchingdialog-record">Record MatchingDialog</button><div id="fixtures"></div><script>'+script+'</script>')
for p in [o/'matchingdialog-cases.json',r/'docs/replica/source/matchingdialog-cases.json']:p.write_text(json.dumps(cases,ensure_ascii=False,indent=2)+'\n')
print(len(cases),'literal drawer cases')
